"""Real WAV fixtures generated by the standard library, with optional RIFF metadata."""
import io
import struct
import wave


def pcm_wav(pcm, *, sample_rate=32000, channels=1, sample_width=2,
            metadata=False, unknown_sizes=False):
    buffer = io.BytesIO()
    with wave.open(buffer, "wb") as output:
        output.setnchannels(channels)
        output.setsampwidth(sample_width)
        output.setframerate(sample_rate)
        output.writeframes(pcm)
    wav = buffer.getvalue()
    extra = b""
    if metadata:
        # A valid LIST/INFO chunk and an odd-length padded unknown chunk.
        info = b"INFOINAM" + struct.pack("<I", 4) + b"test"
        extra = b"LIST" + struct.pack("<I", len(info)) + info
        extra += b"JUNK" + struct.pack("<I", 3) + b"pad\0"
    wav = wav[:36] + extra + wav[36:]
    wav = wav[:4] + struct.pack("<I", len(wav) - 8) + wav[8:]
    if unknown_sizes:
        data_size_offset = 40 + len(extra)
        wav = wav[:4] + b"\xff" * 4 + wav[8:data_size_offset] + b"\xff" * 4 + wav[data_size_offset + 4:]
    return wav
